choose.when:
SELECT r.report_id
  FROM tb_server_report r
 WHERE r.server_id = #{serverId}
   AND (SELECT COUNT(*) FROM tb_server_report m
         WHERE m.server_id = r.server_id
           AND (m.req_dt > r.req_dt OR (m.req_dt = r.req_dt AND m.report_id > r.report_id))) >= #{keep}

choose.otherwise:
SELECT x.report_id
  FROM (
        SELECT r.report_id,
               ROW_NUMBER() OVER (ORDER BY r.req_dt DESC, r.report_id DESC) AS rn
          FROM tb_server_report r
         WHERE r.server_id = #{serverId}
       ) x
 WHERE x.rn > #{keep}

mapper.delete:
DELETE FROM tb_server_report
 WHERE report_id IN
#{id}
